import asyncio,sqlite3,json,os
DB='/app/data/huddle.db'
def db(): c=sqlite3.connect(DB);c.row_factory=sqlite3.Row;return c
def tok(t):
 c=db();r=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(t,)).fetchone();c.close();return r
async def main():
 clients=set(); joins={}
 async def client(r,w):
  user=None;nick=None;registered=False; chans=set(); clients.add((r,w))
  async def send(s):w.write((s+'\r\n').encode());await w.drain()
  try:
   while True:
    line=await r.readline()
    if not line:break
    z=line.decode(errors='ignore').strip('\r\n');p=z.split(' ',1);cmd=p[0].upper();arg=p[1] if len(p)>1 else ''
    if cmd=='PASS': user=tok(arg.strip())
    elif cmd=='NICK':
     n=arg.lstrip(':').split()[0] if arg else ''
     if any(x[0]==n for x in joins.values()):await send(f':irc 433 * {n} :Nickname in use')
     else:nick=n
    elif cmd=='USER':
     if not user:await send(':irc 464 * :Password incorrect');continue
     if not nick:continue
     registered=True
     for n in ('001','002','003','004','005'):await send(f':irc {n} {nick} :Welcome')
