import asyncio,json,sqlite3
DB='/app/data/huddle.db'; clients=[]
def db():
 c=sqlite3.connect(DB,timeout=5); c.row_factory=sqlite3.Row; return c
def tok(t):
 c=db(); r=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(t,)).fetchone(); c.close(); return r
def channel(name):
 q=name[1:] if name.startswith('#') else name
 if '/' not in q:return None
 slug,ch=q.split('/',1); c=db(); r=c.execute('SELECT c.*,w.slug FROM channels c JOIN workspaces w ON w.id=c.workspace_id WHERE w.slug=? AND c.name=? AND c.is_archived=0',(slug,ch)).fetchone(); c.close(); return r
async def gateway(reader,writer):
 user=None;nick=None;registered=False;joined={};seen={}
 async def send(x):
  writer.write((x+'\r\n').encode()); await writer.drain()
 clients.append({'writer':writer,'nick':None,'joined':joined})
 try:
  while True:
   try: line=await asyncio.wait_for(reader.readline(),.2)
   except asyncio.TimeoutError: line=b''
   if line:
    z=line.decode(errors='ignore').strip('\r\n'); p=z.split(' ',1); cmd=p[0].upper(); arg=p[1] if len(p)>1 else ''
    if cmd=='PASS':
     user=tok(arg.strip())
     if not user: await send(':irc 464 * :Password incorrect')
    elif cmd=='NICK':
     n=arg.split()[0] if arg else ''
     if any(x['nick']==n and x['writer'] is not writer for x in clients): await send(f':irc 433 {nick or "*"} {n} :Nickname in use')
     else: nick=n; [x.update(nick=nick) for x in clients if x['writer'] is writer]
    elif cmd=='USER':
     if not user: await send(f':irc 464 {nick or "*"} :Password incorrect')
     elif nick and not registered:
      registered=True
      for code in ('001','002','003','004','005'): await send(f':irc {code} {nick} :Welcome')
      await send(f':irc 422 {nick} :MOTD File is missing')
    elif cmd=='PING': await send(f':irc PONG irc :{arg.lstrip(":")}')
    elif cmd=='QUIT': break
    elif cmd in ('PONG','WHO','LIST','TOPIC','MODE'): pass
    elif cmd=='NAMES':
     await send(f':irc 353 {nick or "*"} = {arg} :{nick or ""}'); await send(f':irc 366 {nick or "*"} {arg} :End of NAMES')
    elif cmd=='JOIN':
     name=arg.split()[0] if arg else ''; ch=channel(name)
     if not ch: await send(f':irc 403 {nick or "*"} {name} :No such channel')
     elif not user: await send(f':irc 464 {nick or "*"} :Password incorrect')
     else:
      c=db(); c.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(ch['workspace_id'],user['id'],'member')); c.execute('INSERT OR IGNORE INTO cmembers VALUES(?,?)',(ch['id'],user['id'])); c.commit(); c.close()
      joined[ch['id']]=name; seen[ch['id']]=0
      await send(f':{nick}!{user["username"]}@host JOIN {name}'); await send(f':irc 353 {nick} = {name} :{nick}'); await send(f':irc 366 {nick} {name} :End of NAMES')
    elif cmd=='PRIVMSG':
     pp=arg.split(' :',1); target=pp[0]; text=pp[1] if len(pp)>1 else ''
     ch=channel(target)
     if ch and user:
      c=db(); c.execute('BEGIN IMMEDIATE'); c.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,datetime("now"))',(ch['id'],user['id'],text.replace('\n',' '))); mid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; c.execute('INSERT OR IGNORE INTO counters VALUES(?,0)',(ch['id'],)); c.execute('UPDATE counters SET n=n+1 WHERE channel_id=?',(ch['id'],)); eid=c.execute('SELECT n FROM counters WHERE channel_id=?',(ch['id'],)).fetchone()[0]; m=dict(c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone()); a=dict(c.execute('SELECT * FROM users WHERE id=?',(user['id'],)).fetchone()); m.update(author=a,parent_id=None,reply_count=0,edited_at=None,files=[],reactions=[],mentions=[]); c.execute('INSERT INTO events VALUES(?,?,?,?)',(ch['id'],eid,'message.created',json.dumps({'type':'message.created','event_id':eid,'channel_id':ch['id'],'message':m,'irc_author':user['id']}))); c.commit(); c.close()
    elif cmd: await send(f':irc 421 {nick or "*"} {cmd} :Unknown command')
   c=db()
   for cid,name in joined.items():
    for row in c.execute('SELECT event_id,payload FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id',(cid,seen.get(cid,0))):
     x=json.loads(row['payload']); seen[cid]=row['event_id']; m=x.get('message',{}); a=c.execute('SELECT username FROM users WHERE id=?',(m.get('author_id'),)).fetchone()
     if a and not (x.get('irc_author')==user['id'] and m.get('author_id')==user['id']): await send(f':{a["username"]}!{a["username"]}@host PRIVMSG {name} :{m.get("body","")}')
   c.close()
 except Exception as e: print('IRC client error',repr(e),flush=True)
 finally:
  clients[:]=[x for x in clients if x['writer'] is not writer]; writer.close(); await writer.wait_closed()
async def main():
 s=await asyncio.start_server(gateway,'0.0.0.0',6667)
 async with s: await s.serve_forever()
asyncio.run(main())
